  ('Armatura di cuoio borchiato', 'armor', '2014', null, null, '{"name":"Armatura di cuoio borchiato","original_name":"Studded Leather Armor","category":"armor","rules_version":"2014","qty":1,"weight":5.9,"volume":0,"value_cp":4500,"image_url":null,"notes":"","is_magic":false,"attunement_active":false,"source_id":"studded-leather-armor","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/studded-leather-armor","source_kind":"equipment","original_category":"armatura","cost":{"quantita":45,"moneta":"mo"},"equipable":true,"compatible_equip_slots":["chest"],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"armor_type":"light","is_shield":false,"armor_class":12,"armor_bonus":0,"shield_bonus":0,"armor_uses_dexterity":true,"armor_dexterity_cap":0,"minimum_strength":0,"stealth_disadvantage":false}'::jsonb),
  ('Abaco', 'gear', '2014', null, 'Un telaio di calcolo utile per contabilità, commerci e rompicapi numerici. Può aiutare a verificare registri, dividere ricompense o rendere credibile la copertura di un mercante.', '{"name":"Abaco","original_name":"Abacus","category":"gear","rules_version":"2014","qty":1,"weight":0.91,"volume":0,"value_cp":200,"image_url":null,"notes":"Un telaio di calcolo utile per contabilità, commerci e rompicapi numerici. Può aiutare a verificare registri, dividere ricompense o rendere credibile la copertura di un mercante.","is_magic":false,"attunement_active":false,"source_id":"abacus","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/abacus","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Acido (fiala)', 'gear', '2014', null, 'Come azione, puoi spruzzare il contenuto di questa fiala su una creatura entro 5 piedi da te oppure lanciarla fino a 20 piedi di distanza, frantumandola all’impatto. In entrambi i casi, effettua un attacco a distanza contro una creatura o un oggetto, trattando l’acido come un’arma improvvisata.

In caso di colpo andato a segno, il bersaglio subisce 2d6 danni da acido.', '{"name":"Acido (fiala)","original_name":"Acid (vial)","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":2500,"image_url":null,"notes":"Come azione, puoi spruzzare il contenuto di questa fiala su una creatura entro 5 piedi da te oppure lanciarla fino a 20 piedi di distanza, frantumandola all’impatto. In entrambi i casi, effettua un attacco a distanza contro una creatura o un oggetto, trattando l’acido come un’arma improvvisata.\n\nIn caso di colpo andato a segno, il bersaglio subisce 2d6 danni da acido.","is_magic":false,"attunement_active":false,"source_id":"acid-vial","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/acid-vial","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":25,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Fuoco dell’alchimista (ampolla)', 'gear', '2014', null, 'Questo fluido appiccicoso e adesivo prende fuoco se esposto all’aria.

Come azione, puoi lanciare questa fiaschetta fino a 20 piedi di distanza, frantumandola all’impatto. Effettua un attacco a distanza contro una creatura o un oggetto, trattando il fuoco dell’alchimista come un’arma improvvisata.

In caso di colpo andato a segno, il bersaglio subisce 1d4 danni da fuoco all’inizio di ciascuno dei propri turni. Una creatura può porre fine a questi danni utilizzando la propria azione per effettuare un tiro di Destrezza con CD 10 per spegnere le fiamme.', '{"name":"Fuoco dell’alchimista (ampolla)","original_name":"Alchemist''s fire (flask)","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":5000,"image_url":null,"notes":"Questo fluido appiccicoso e adesivo prende fuoco se esposto all’aria.\n\nCome azione, puoi lanciare questa fiaschetta fino a 20 piedi di distanza, frantumandola all’impatto. Effettua un attacco a distanza contro una creatura o un oggetto, trattando il fuoco dell’alchimista come un’arma improvvisata.\n\nIn caso di colpo andato a segno, il bersaglio subisce 1d4 danni da fuoco all’inizio di ciascuno dei propri turni. Una creatura può porre fine a questi danni utilizzando la propria azione per effettuare un tiro di Destrezza con CD 10 per spegnere le fiamme.","is_magic":false,"attunement_active":false,"source_id":"alchemists-fire-flask","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/alchemists-fire-flask","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":50,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Cassetta delle elemosine', 'gear', '2014', null, 'Una piccola scatola per le elemosine, che di solito si trova nello zaino di un sacerdote.', '{"name":"Cassetta delle elemosine","original_name":"Alms box","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":0,"image_url":null,"notes":"Una piccola scatola per le elemosine, che di solito si trova nello zaino di un sacerdote.","is_magic":false,"attunement_active":false,"source_id":"alms-box","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/alms-box","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":0,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Amuleto', 'gear', '2014', null, 'Un simbolo sacro è una rappresentazione di un dio o di un pantheon. Può trattarsi di un amuleto che raffigura un simbolo rappresentativo di una divinità, dello stesso simbolo accuratamente inciso o intarsiato come emblema su uno scudo, oppure di una minuscola scatola contenente un frammento di una reliquia sacra.

L’Appendice B elenca i simboli comunemente associati a molte divinità del multiverso. Un chierico o un paladino può utilizzare un simbolo sacro come focus per lanciare incantesimi. Per utilizzare il simbolo in questo modo, l’incantatore deve tenerlo in mano, indossarlo in modo visibile o portarlo su uno scudo.', '{"name":"Amuleto","original_name":"Amulet","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":500,"image_url":null,"notes":"Un simbolo sacro è una rappresentazione di un dio o di un pantheon. Può trattarsi di un amuleto che raffigura un simbolo rappresentativo di una divinità, dello stesso simbolo accuratamente inciso o intarsiato come emblema su uno scudo, oppure di una minuscola scatola contenente un frammento di una reliquia sacra.\n\nL’Appendice B elenca i simboli comunemente associati a molte divinità del multiverso. Un chierico o un paladino può utilizzare un simbolo sacro come focus per lanciare incantesimi. Per utilizzare il simbolo in questo modo, l’incantatore deve tenerlo in mano, indossarlo in modo visibile o portarlo su uno scudo.","is_magic":false,"attunement_active":false,"source_id":"amulet","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/amulet","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"holy-symbols","bundle_contents":[]}'::jsonb),
  ('Antitossina (fiala)', 'gear', '2014', null, 'Una creatura che beve questa fiala di liquido ottiene vantaggio sui tiri salvezza contro il veleno per 1 ora. Non conferisce alcun beneficio ai non morti o ai costrutti.', '{"name":"Antitossina (fiala)","original_name":"Antitoxin (vial)","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":5000,"image_url":null,"notes":"Una creatura che beve questa fiala di liquido ottiene vantaggio sui tiri salvezza contro il veleno per 1 ora. Non conferisce alcun beneficio ai non morti o ai costrutti.","is_magic":false,"attunement_active":false,"source_id":"antitoxin-vial","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/antitoxin-vial","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":50,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Freccia', 'consumable', '2014', null, 'Munizione per archi, normalmente conservata in una faretra. Recuperare le frecce dopo uno scontro o controllarne la scorta può diventare importante durante viaggi lunghi.', '{"name":"Freccia","original_name":"Arrow","category":"consumable","rules_version":"2014","qty":20,"weight":0.45,"volume":0,"value_cp":100,"image_url":null,"notes":"Munizione per archi, normalmente conservata in una faretra. Recuperare le frecce dopo uno scontro o controllarne la scorta può diventare importante durante viaggi lunghi.","is_magic":false,"attunement_active":false,"source_id":"arrow","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/arrow","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":"arrow","gear_category":"ammunition","bundle_contents":[]}'::jsonb),
  ('Zaino', 'container', '2014', null, 'Uno zaino da viaggio per organizzare provviste e attrezzatura. Usalo come contenitore per separare ciò che il personaggio trasporta dagli oggetti lasciati altrove.', '{"name":"Zaino","original_name":"Backpack","category":"container","rules_version":"2014","qty":1,"weight":2.27,"volume":0,"value_cp":200,"image_url":null,"notes":"Uno zaino da viaggio per organizzare provviste e attrezzatura. Usalo come contenitore per separare ciò che il personaggio trasporta dagli oggetti lasciati altrove.","is_magic":false,"attunement_active":false,"source_id":"backpack","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/backpack","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Biglie metalliche (sacchetto da 1.000)', 'gear', '2014', null, 'Come azione, puoi versare queste minuscole palline di metallo dal loro sacchetto per coprire un’area quadrata di 10 piedi di lato.

Una creatura che si muove attraverso l’area coperta deve superare un tiro salvezza di Destrezza con CD 10 o cadere a terra.

Una creatura che si muove attraverso l’area a metà velocità non deve effettuare il tiro di salvataggio.', '{"name":"Biglie metalliche (sacchetto da 1.000)","original_name":"Ball bearings (bag of 1,000)","category":"gear","rules_version":"2014","qty":1,"weight":0.91,"volume":0,"value_cp":100,"image_url":null,"notes":"Come azione, puoi versare queste minuscole palline di metallo dal loro sacchetto per coprire un’area quadrata di 10 piedi di lato.\n\nUna creatura che si muove attraverso l’area coperta deve superare un tiro salvezza di Destrezza con CD 10 o cadere a terra.\n\nUna creatura che si muove attraverso l’area a metà velocità non deve effettuare il tiro di salvataggio.","is_magic":false,"attunement_active":false,"source_id":"ball-bearings-bag-of-1000","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/ball-bearings-bag-of-1000","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Barile', 'container', '2014', null, 'Un robusto recipiente di legno adatto a liquidi, viveri o materiali sfusi. Può offrire copertura improvvisata, essere fatto rotolare o nascondere oggetti ingombranti.', '{"name":"Barile","original_name":"Barrel","category":"container","rules_version":"2014","qty":1,"weight":31.75,"volume":0,"value_cp":200,"image_url":null,"notes":"Un robusto recipiente di legno adatto a liquidi, viveri o materiali sfusi. Può offrire copertura improvvisata, essere fatto rotolare o nascondere oggetti ingombranti.","is_magic":false,"attunement_active":false,"source_id":"barrel","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/barrel","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Cesta', 'container', '2014', null, 'Un contenitore leggero e facilmente accessibile per cibo, erbe o piccoli oggetti. È pratico quando conta raggiungere il contenuto rapidamente, ma protegge poco da acqua e urti.', '{"name":"Cesta","original_name":"Basket","category":"container","rules_version":"2014","qty":1,"weight":0.91,"volume":0,"value_cp":40,"image_url":null,"notes":"Un contenitore leggero e facilmente accessibile per cibo, erbe o piccoli oggetti. È pratico quando conta raggiungere il contenuto rapidamente, ma protegge poco da acqua e urti.","is_magic":false,"attunement_active":false,"source_id":"basket","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/basket","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":4,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Giaciglio', 'gear', '2014', null, 'Un giaciglio trasportabile per dormire lontano da locande e accampamenti attrezzati. Può isolare dal terreno freddo o essere usato come coperta e imbottitura improvvisata.', '{"name":"Giaciglio","original_name":"Bedroll","category":"gear","rules_version":"2014","qty":1,"weight":3.18,"volume":0,"value_cp":100,"image_url":null,"notes":"Un giaciglio trasportabile per dormire lontano da locande e accampamenti attrezzati. Può isolare dal terreno freddo o essere usato come coperta e imbottitura improvvisata.","is_magic":false,"attunement_active":false,"source_id":"bedroll","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/bedroll","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Campanella', 'gear', '2014', null, 'Una piccola campana dal suono riconoscibile. Legata a un filo può diventare un allarme rudimentale, oppure servire per segnali, rituali e distrazioni.', '{"name":"Campanella","original_name":"Bell","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":100,"image_url":null,"notes":"Una piccola campana dal suono riconoscibile. Legata a un filo può diventare un allarme rudimentale, oppure servire per segnali, rituali e distrazioni.","is_magic":false,"attunement_active":false,"source_id":"bell","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/bell","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Coperta', 'gear', '2014', null, 'Una coperta pesante utile contro freddo e intemperie. Può avvolgere una creatura, proteggere oggetti fragili, soffocare una piccola fiamma o improvvisare una barella.', '{"name":"Coperta","original_name":"Blanket","category":"gear","rules_version":"2014","qty":1,"weight":1.36,"volume":0,"value_cp":50,"image_url":null,"notes":"Una coperta pesante utile contro freddo e intemperie. Può avvolgere una creatura, proteggere oggetti fragili, soffocare una piccola fiamma o improvvisare una barella.","is_magic":false,"attunement_active":false,"source_id":"blanket","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/blanket","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Block and tackle', 'gear', '2014', null, 'Un sistema di carrucole con un cavo che le attraversa e un gancio per agganciarlo agli oggetti, il paranco, ti permette di sollevare fino a quattro volte il peso che potresti sollevare normalmente.', '{"name":"Block and tackle","original_name":"Block and tackle","category":"gear","rules_version":"2014","qty":1,"weight":2.27,"volume":0,"value_cp":100,"image_url":null,"notes":"Un sistema di carrucole con un cavo che le attraversa e un gancio per agganciarlo agli oggetti, il paranco, ti permette di sollevare fino a quattro volte il peso che potresti sollevare normalmente.","is_magic":false,"attunement_active":false,"source_id":"block-and-tackle","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/block-and-tackle","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
