  ('Ago per cerbottana', 'consumable', '2014', null, 'Munizione sottile per cerbottana. Gli aghi sono facili da trasportare e nascondere, ma devono essere conservati con cura per non danneggiarsi o ferire accidentalmente chi li porta.', '{"name":"Ago per cerbottana","original_name":"Blowgun needle","category":"consumable","rules_version":"2014","qty":50,"weight":0.45,"volume":0,"value_cp":100,"image_url":null,"notes":"Munizione sottile per cerbottana. Gli aghi sono facili da trasportare e nascondere, ma devono essere conservati con cura per non danneggiarsi o ferire accidentalmente chi li porta.","is_magic":false,"attunement_active":false,"source_id":"blowgun-needle","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/blowgun-needle","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":"needle","gear_category":"ammunition","bundle_contents":[]}'::jsonb),
  ('Libro', 'gear', '2014', null, 'Un libro può contenere poesie, resoconti storici, informazioni relative a un particolare campo del sapere, diagrammi e note su congegni gnomici, o praticamente qualsiasi altra cosa che possa essere rappresentata tramite testo o immagini. Un libro di incantesimi è un libro degli incantesimi (descritto più avanti in questa sezione).', '{"name":"Libro","original_name":"Book","category":"gear","rules_version":"2014","qty":1,"weight":2.27,"volume":0,"value_cp":2500,"image_url":null,"notes":"Un libro può contenere poesie, resoconti storici, informazioni relative a un particolare campo del sapere, diagrammi e note su congegni gnomici, o praticamente qualsiasi altra cosa che possa essere rappresentata tramite testo o immagini. Un libro di incantesimi è un libro degli incantesimi (descritto più avanti in questa sezione).","is_magic":false,"attunement_active":false,"source_id":"book","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/book","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":25,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Bottiglia, bicchiere', 'container', '2014', null, 'Un recipiente di vetro per liquidi, campioni o ingredienti. È impermeabile ma fragile: può conservare una prova, raccogliere una sostanza o produrre frammenti e rumore se rotto.', '{"name":"Bottiglia, bicchiere","original_name":"Bottle, glass","category":"container","rules_version":"2014","qty":1,"weight":0.91,"volume":0,"value_cp":200,"image_url":null,"notes":"Un recipiente di vetro per liquidi, campioni o ingredienti. È impermeabile ma fragile: può conservare una prova, raccogliere una sostanza o produrre frammenti e rumore se rotto.","is_magic":false,"attunement_active":false,"source_id":"bottle-glass","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/bottle-glass","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Secchio', 'container', '2014', null, 'Un secchio per trasportare acqua, sabbia o materiali sfusi. Può servire per spegnere incendi, svuotare una stanza allagata o improvvisare un recipiente e una trappola rumorosa.', '{"name":"Secchio","original_name":"Bucket","category":"container","rules_version":"2014","qty":1,"weight":0.91,"volume":0,"value_cp":5,"image_url":null,"notes":"Un secchio per trasportare acqua, sabbia o materiali sfusi. Può servire per spegnere incendi, svuotare una stanza allagata o improvvisare un recipiente e una trappola rumorosa.","is_magic":false,"attunement_active":false,"source_id":"bucket","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/bucket","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Dotazione da scassinatore', 'container', '2014', null, 'Una dotazione organizzata per infiltrazioni ed esplorazione urbana. Contiene strumenti utili per creare allarmi, superare ostacoli e affrontare ambienti bui senza dipendere da rifornimenti immediati.', '{"name":"Dotazione da scassinatore","original_name":"Burglar''s Pack","category":"container","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":1600,"image_url":null,"notes":"Una dotazione organizzata per infiltrazioni ed esplorazione urbana. Contiene strumenti utili per creare allarmi, superare ostacoli e affrontare ambienti bui senza dipendere da rifornimenti immediati.","is_magic":false,"attunement_active":false,"source_id":"burglars-pack","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/burglars-pack","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":16,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"equipment-packs","bundle_contents":[{"source_id":"backpack","name":"Backpack","url":"/api/2014/equipment/backpack","quantity":1},{"source_id":"ball-bearings-bag-of-1000","name":"Ball bearings (bag of 1,000)","url":"/api/2014/equipment/ball-bearings-bag-of-1000","quantity":1},{"source_id":"string-10-feet","name":"String (10 feet)","url":"/api/2014/equipment/string-10-feet","quantity":1},{"source_id":"bell","name":"Bell","url":"/api/2014/equipment/bell","quantity":1},{"source_id":"candle","name":"Candle","url":"/api/2014/equipment/candle","quantity":5},{"source_id":"crowbar","name":"Crowbar","url":"/api/2014/equipment/crowbar","quantity":1},{"source_id":"hammer","name":"Hammer","url":"/api/2014/equipment/hammer","quantity":1},{"source_id":"piton","name":"Piton","url":"/api/2014/equipment/piton","quantity":10},{"source_id":"lantern-hooded","name":"Lantern, hooded","ur