  ('Triboli', 'gear', '2014', null, 'Come azione, puoi spargere un sacchetto di caltrops per coprire un''area quadrata di 5 piedi di lato.

Qualsiasi creatura che entri nell''area deve superare un tiro salvezza di Destrezza con CD 15 oppure smettere di muoversi in questo turno e subire 1 danno perforante.

Subire questo danno riduce la velocità di movimento della creatura di 10 piedi finché non recupera almeno 1 punto ferita.

Una creatura che si muove attraverso l’area a metà velocità non deve effettuare il tiro salvezza.', '{"name":"Triboli","original_name":"Caltrops","category":"gear","rules_version":"2014","qty":1,"weight":0.91,"volume":0,"value_cp":5,"image_url":null,"notes":"Come azione, puoi spargere un sacchetto di caltrops per coprire un''area quadrata di 5 piedi di lato.\n\nQualsiasi creatura che entri nell''area deve superare un tiro salvezza di Destrezza con CD 15 oppure smettere di muoversi in questo turno e subire 1 danno perforante.\n\nSubire questo danno riduce la velocità di movimento della creatura di 10 piedi finché non recupera almeno 1 punto ferita.\n\nUna creatura che si muove attraverso l’area a metà velocità non deve effettuare il tiro salvezza.","is_magic":false,"attunement_active":false,"source_id":"caltrops","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/caltrops","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Candela', 'gear', '2014', null, 'Per 1 ora, una candela diffonde luce intensa in un raggio di 5 piedi e luce fioca per altri 5 piedi.', '{"name":"Candela","original_name":"Candle","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":1,"image_url":null,"notes":"Per 1 ora, una candela diffonde luce intensa in un raggio di 5 piedi e luce fioca per altri 5 piedi.","is_magic":false,"attunement_active":false,"source_id":"candle","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/candle","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Case, dardo da balestra', 'container', '2014', null, 'Questa custodia in legno può contenere fino a venti dardi da balestra.', '{"name":"Case, dardo da balestra","original_name":"Case, crossbow bolt","category":"container","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":100,"image_url":null,"notes":"Questa custodia in legno può contenere fino a venti dardi da balestra.","is_magic":false,"attunement_active":false,"source_id":"case-crossbow-bolt","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/case-crossbow-bolt","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
