  ('Catena (3 m)', 'gear', '2014', null, 'Una catena ha 10 punti ferita. Può essere spezzata con un tiro di Forza riuscito con CD 20.', '{"name":"Catena (3 m)","original_name":"Chain (10 feet)","category":"gear","rules_version":"2014","qty":1,"weight":4.54,"volume":0,"value_cp":500,"image_url":null,"notes":"Una catena ha 10 punti ferita. Può essere spezzata con un tiro di Forza riuscito con CD 20.","is_magic":false,"attunement_active":false,"source_id":"chain-10-feet","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/chain-10-feet","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Gesso (1 pezzo)', 'gear', '2014', null, 'Un pezzo di gesso per segnare muri, pavimenti e percorsi. È utile per non perdersi in un dungeon, lasciare messaggi discreti o evidenziare porte e oggetti già controllati.', '{"name":"Gesso (1 pezzo)","original_name":"Chalk (1 piece)","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":1,"image_url":null,"notes":"Un pezzo di gesso per segnare muri, pavimenti e percorsi. È utile per non perdersi in un dungeon, lasciare messaggi discreti o evidenziare porte e oggetti già controllati.","is_magic":false,"attunement_active":false,"source_id":"chalk-1-piece","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/chalk-1-piece","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Forziere', 'container', '2014', null, 'Un contenitore rigido per custodire oggetti e monete. Può essere chiuso, nascosto o trasformato in esca; il suo ingombro lo rende più adatto a una base che al trasporto quotidiano.', '{"name":"Forziere","original_name":"Chest","category":"container","rules_version":"2014","qty":1,"weight":11.34,"volume":0,"value_cp":500,"image_url":null,"notes":"Un contenitore rigido per custodire oggetti e monete. Può essere chiuso, nascosto o trasformato in esca; il suo ingombro lo rende più adatto a una base che al trasporto quotidiano.","is_magic":false,"attunement_active":false,"source_id":"chest","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/chest","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Kit da arrampicata', 'gear', '2014', null, 'Un kit da scalatore include chiodi speciali, puntali per gli stivali, guanti e un''imbracatura. Puoi usare il kit da scalatore come azione per ancorarti; quando lo fai, non puoi cadere a più di 25 piedi dal punto in cui ti sei ancorato e non puoi arrampicarti a più di 25 piedi di distanza da quel punto senza sganciare l’ancoraggio.', '{"name":"Kit da arrampicata","original_name":"Climber''s Kit","category":"gear","rules_version":"2014","qty":1,"weight":5.44,"volume":0,"value_cp":2500,"image_url":null,"notes":"Un kit da scalatore include chiodi speciali, puntali per gli stivali, guanti e un''imbracatura. Puoi usare il kit da scalatore come azione per ancorarti; quando lo fai, non puoi cadere a più di 25 piedi dal punto in cui ti sei ancorato e non puoi arrampicarti a più di 25 piedi di distanza da quel punto senza sganciare l’ancoraggio.","is_magic":false,"attunement_active":false,"source_id":"climbers-kit","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/climbers-kit","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":25,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"kits","bundle_contents":[]}'::jsonb),
  ('Abbigliamento, comune', 'gear', '2014', null, 'Abiti semplici adatti alla vita quotidiana. Aiutano a confondersi tra lavoratori e viaggiatori senza attirare l’attenzione che armature o vestiti raffinati potrebbero provocare.', '{"name":"Abbigliamento, comune","original_name":"Clothes, common","category":"gear","rules_version":"2014","qty":1,"weight":1.36,"volume":0,"value_cp":50,"image_url":null,"notes":"Abiti semplici adatti alla vita quotidiana. Aiutano a confondersi tra lavoratori e viaggiatori senza attirare l’attenzione che armature o vestiti raffinati potrebbero provocare.","is_magic":false,"attunement_active":false,"source_id":"clothes-common","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/clothes-common","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Abbigliamento, costumi', 'gear', '2014', null, 'Un costume pensato per spettacoli e travestimenti. Insieme a una buona interpretazione può sostenere una falsa identità, creare una distrazione o rendere memorabile un’esibizione.', '{"name":"Abbigliamento, costumi","original_name":"Clothes, costume","category":"gear","rules_version":"2014","qty":1,"weight":1.81,"volume":0,"value_cp":500,"image_url":null,"notes":"Un costume pensato per spettacoli e travestimenti. Insieme a una buona interpretazione può sostenere una falsa identità, creare una distrazione o rendere memorabile un’esibizione.","is_magic":false,"attunement_active":false,"source_id":"clothes-costume","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/clothes-costume","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Abbigliamento, raffinato', 'gear', '2014', null, 'Abiti di qualità adatti a corti, ricevimenti e incontri formali. Non garantiscono successo sociale, ma possono evitare che il personaggio venga escluso prima ancora di poter parlare.', '{"name":"Abbigliamento, raffinato","original_name":"Clothes, fine","category":"gear","rules_version":"2014","qty":1,"weight":2.72,"volume":0,"value_cp":1500,"image_url":null,"notes":"Abiti di qualità adatti a corti, ricevimenti e incontri formali. Non garantiscono successo sociale, ma possono evitare che il personaggio venga escluso prima ancora di poter parlare.","is_magic":false,"attunement_active":false,"source_id":"clothes-fine","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/clothes-fine","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":15,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Abbigliamento, da viaggio', 'gear', '2014', null, 'Vestiti resistenti pensati per lunghi viaggi e clima variabile. Tasche, mantello e tessuti robusti li rendono adatti a esploratori, messaggeri e avventurieri.', '{"name":"Abbigliamento, da viaggio","original_name":"Clothes, traveler''s","category":"gear","rules_version":"2014","qty":1,"weight":1.81,"volume":0,"value_cp":200,"image_url":null,"notes":"Vestiti resistenti pensati per lunghi viaggi e clima variabile. Tasche, mantello e tessuti robusti li rendono adatti a esploratori, messaggeri e avventurieri.","is_magic":false,"attunement_active":false,"source_id":"clothes-travelers","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/clothes-travelers","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Borsa delle componenti', 'gear', '2014', null, 'Una sacca per componenti è una piccola sacca da cintura in pelle a tenuta stagna dotata di scomparti per contenere tutti i componenti materiali e gli altri oggetti speciali necessari per lanciare i tuoi incantesimi, ad eccezione di quei componenti che hanno un costo specifico (come indicato nella descrizione di un incantesimo).', '{"name":"Borsa delle componenti","original_name":"Component pouch","category":"gear","rules_version":"2014","qty":1,"weight":0.91,"volume":0,"value_cp":2500,"image_url":null,"notes":"Una sacca per componenti è una piccola sacca da cintura in pelle a tenuta stagna dotata di scomparti per contenere tutti i componenti materiali e gli altri oggetti speciali necessari per lanciare i tuoi incantesimi, ad eccezione di quei componenti che hanno un costo specifico (come indicato nella descrizione di un incantesimo).","is_magic":false,"attunement_active":false,"source_id":"component-pouch","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/component-pouch","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":25,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Quadrello per balestra', 'consumable', '2014', null, 'Munizione per balestre, normalmente trasportata in una custodia. Tenere separati i quadrelli dagli altri oggetti evita danni e permette di controllarne rapidamente la disponibilità.', '{"name":"Quadrello per balestra","original_name":"Crossbow bolt","category":"consumable","rules_version":"2014","qty":20,"weight":0.68,"volume":0,"value_cp":100,"image_url":null,"notes":"Munizione per balestre, normalmente trasportata in una custodia. Tenere separati i quadrelli dagli altri oggetti evita danni e permette di controllarne rapidamente la disponibilità.","is_magic":false,"attunement_active":false,"source_id":"crossbow-bolt","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/crossbow-bolt","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":"bolt","gear_category":"ammunition","bundle_contents":[]}'::jsonb),
  ('Piede di porco', 'gear', '2014', null, 'L''uso di un piede di porco garantisce un vantaggio ai tiri di Forza nei casi in cui sia possibile sfruttare la leva del piede di porco.', '{"name":"Piede di porco","original_name":"Crowbar","category":"gear","rules_version":"2014","qty":1,"weight":2.27,"volume":0,"value_cp":200,"image_url":null,"notes":"L''uso di un piede di porco garantisce un vantaggio ai tiri di Forza nei casi in cui sia possibile sfruttare la leva del piede di porco.","is_magic":false,"attunement_active":false,"source_id":"crowbar","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/crowbar","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Crystal', 'gear', '2014', null, 'Un focus arcano è un oggetto speciale — una sfera, un cristallo, una verga, un bastone appositamente costruito, un pezzo di legno simile a una bacchetta o un oggetto simile — progettato per incanalare il potere degli incantesimi arcani. Uno stregone, un warlock o un mago può utilizzare tale oggetto come focus per lanciare incantesimi.', '{"name":"Crystal","original_name":"Crystal","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":1000,"image_url":null,"notes":"Un focus arcano è un oggetto speciale — una sfera, un cristallo, una verga, un bastone appositamente costruito, un pezzo di legno simile a una bacchetta o un oggetto simile — progettato per incanalare il potere degli incantesimi arcani. Uno stregone, un warlock o un mago può utilizzare tale oggetto come focus per lanciare incantesimi.","is_magic":false,"attunement_active":false,"source_id":"crystal","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/crystal","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":10,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"arcane-foci","bundle_contents":[]}'::jsonb),
  ('Dotazione da diplomatico', 'container', '2014', null, 'Una dotazione per viaggi ufficiali, corrispondenza e incontri formali. Offre il necessario per presentarsi con ordine, scrivere documenti e proteggere lettere o mappe.', '{"name":"Dotazione da diplomatico","original_name":"Diplomat''s Pack","category":"container","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":3900,"image_url":null,"notes":"Una dotazione per viaggi ufficiali, corrispondenza e incontri formali. Offre il necessario per presentarsi con ordine, scrivere documenti e proteggere lettere o mappe.","is_magic":false,"attunement_active":false,"source_id":"diplomats-pack","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/diplomats-pack","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":39,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"equipment-packs","bundle_contents":[{"source_id":"chest","name":"Chest","url":"/api/2014/equipment/chest","quantity":1},{"source_id":"case-map-or-scroll","name":"Case, map or scroll","url":"/api/2014/equipment/case-map-or-scroll","quantity":2},{"source_id":"clothes-fine","name":"Clothes, fine","url":"/api/2014/equipment/clothes-fine","quantity":1},{"source_id":"ink-1-ounce-bottle","name":"Ink (1 ounce bottle)","url":"/api/2014/equipment/ink-1-ounce-bottle","quantity":1},{"source_id":"ink-pen","name":"Ink pen","url":"/api/2014/equipment/ink-pen","quantity":1},{"source_id":"lamp","name":"Lamp","url":"/api/2014/equipment/lamp","quantity":1},{"source_id":"oil-flask","name":"Oil (flask)","url":"/api/2014/equipment/oil-flask","quantity":2},{"source_id":"paper-one-sheet","name":"Paper (one sheet)","url":"/api/2014/equipment/paper-one-sheet","quantity":5},{"source_id":"perfume-vial","name":"Perfume (vial)","url":"/api/2014/equipment/perfume-vial","quantity":1},{"source_id":"sealing-wax","name":"Sealing wax","url":"/api/2014/equipment/sealing-wax","quantity":1},{"source_id":"soap","name":"Soap","url":"/api/2014/equipment/soap","quantity":1}]}'::jsonb),
  ('Kit di travestimento', 'gear', '2014', null, 'Questa trousse contenente cosmetici, tintura per capelli e piccoli oggetti di scena ti permette di creare travestimenti che modificano il tuo aspetto fisico. La competenza nell’uso di questo kit ti consente di aggiungere il tuo bonus di competenza a qualsiasi prova di abilità che effettui per creare un travestimento visivo.', '{"name":"Kit di travestimento","original_name":"Disguise Kit","category":"gear","rules_version":"2014","qty":1,"weight":1.36,"volume":0,"value_cp":2500,"image_url":null,"notes":"Questa trousse contenente cosmetici, tintura per capelli e piccoli oggetti di scena ti permette di creare travestimenti che modificano il tuo aspetto fisico. La competenza nell’uso di questo kit ti consente di aggiungere il tuo bonus di competenza a qualsiasi prova di abilità che effettui per creare un travestimento visivo.","is_magic":false,"attunement_active":false,"source_id":"disguise-kit","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/disguise-kit","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":25,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"kits","bundle_contents":[]}'::jsonb),
  ('Dotazione da avventuriero dei dungeon', 'container', '2014', null, 'Una dotazione per esplorare sotterranei e rovine. Riunisce illuminazione, razioni, corda e strumenti robusti per superare passaggi difficili e restare operativi lontano dalla superficie.', '{"name":"Dotazione da avventuriero dei dungeon","original_name":"Dungeoneer''s Pack","category":"container","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":1200,"image_url":null,"notes":"Una dotazione per esplorare sotterranei e rovine. Riunisce illuminazione, razioni, corda e strumenti robusti per superare passaggi difficili e restare operativi lontano dalla superficie.","is_magic":false,"attunement_active":false,"source_id":"dungeoneers-pack","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/dungeoneers-pack","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":12,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"equipment-packs","bundle_contents":[{"source_id":"backpack","name":"Backpack","url":"/api/2014/equipment/backpack","quantity":1},{"source_id":"crowbar","name":"Crowbar","url":"/api/2014/equipment/crowbar","quantity":1},{"source_id":"hammer","name":"Hammer","url":"/api/2014/equipment/hammer","quantity":1},{"source_id":"piton","name":"Piton","url":"/api/2014/equipment/piton","quantity":10},{"source_id":"torch","name":"Torch","url":"/api/2014/equipment/torch","quantity":10},{"source_id":"tinderbox","name":"Tinderbox","url":"/api/2014/equipment/tinderbox","quantity":1},{"source_id":"rations-1-day","name":"Rations (1 day)","url":"/api/2014/equipment/rations-1-day","quantity":10},{"source_id":"waterskin","name":"Waterskin","url":"/api/2014/equipment/waterskin","quantity":1},{"source_id":"rope-hempen-50-feet","name":"Rope, hempen (50 feet)","url":"/api/2014/equipment/rope-hempen-50-feet","quantity":1}]}'::jsonb),
  ('Emblem', 'gear', '2014', null, 'Un simbolo sacro è una rappresentazione di un dio o di un pantheon. Può trattarsi di un amuleto che raffigura un simbolo rappresentativo di una divinità, dello stesso simbolo accuratamente inciso o intarsiato come emblema su uno scudo, oppure di una minuscola scatola contenente un frammento di una reliquia sacra.

L’Appendice B elenca i simboli comunemente associati a molte divinità del multiverso. Un chierico o un paladino può utilizzare un simbolo sacro come focus per lanciare incantesimi. Per utilizzare il simbolo in questo modo, l’incantatore deve tenerlo in mano, indossarlo in modo visibile o portarlo su uno scudo.', '{"name":"Emblem","original_name":"Emblem","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":500,"image_url":null,"notes":"Un simbolo sacro è una rappresentazione di un dio o di un pantheon. Può trattarsi di un amuleto che raffigura un simbolo rappresentativo di una divinità, dello stesso simbolo accuratamente inciso o intarsiato come emblema su uno scudo, oppure di una minuscola scatola contenente un frammento di una reliquia sacra.\n\nL’Appendice B elenca i simboli comunemente associati a molte divinità del multiverso. Un chierico o un paladino può utilizzare un simbolo sacro come focus per lanciare incantesimi. Per utilizzare il simbolo in questo modo, l’incantatore deve tenerlo in mano, indossarlo in modo visibile o portarlo su uno scudo.","is_magic":false,"attunement_active":false,"source_id":"emblem","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/emblem","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"holy-symbols","bundle_contents":[]}'::jsonb),
  ('Dotazione da intrattenitore', 'container', '2014', null, 'Una dotazione per artisti itineranti. Include quanto serve per viaggiare, mantenere una presenza scenica e cambiare aspetto durante spettacoli, coperture o distrazioni.', '{"name":"Dotazione da intrattenitore","original_name":"Entertainer''s Pack","category":"container","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":4000,"image_url":null,"notes":"Una dotazione per artisti itineranti. Include quanto serve per viaggiare, mantenere una presenza scenica e cambiare aspetto durante spettacoli, coperture o distrazioni.","is_magic":false,"attunement_active":false,"source_id":"entertainers-pack","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/entertainers-pack","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":40,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"equipment-packs","bundle_contents":[{"source_id":"backpack","name":"Backpack","url":"/api/2014/equipment/backpack","quantity":1},{"source_id":"bedroll","name":"Bedroll","url":"/api/2014/equipment/bedroll","quantity":1},{"source_id":"clothes-costume","name":"Clothes, costume","url":"/api/2014/equipment/clothes-costume","quantity":2},{"source_id":"candle","name":"Candle","url":"/api/2014/equipment/candle","quantity":5},{"source_id":"rations-1-day","name":"Rations (1 day)","url":"/api/2014/equipment/rations-1-day","quantity":5},{"source_id":"waterskin","name":"Waterskin","url":"/api/2014/equipment/waterskin","quantity":1},{"source_id":"disguise-kit","name":"Disguise Kit","url":"/api/2014/equipment/disguise-kit","quantity":1}]}'::jsonb),
  ('Dotazione da esploratore', 'container', '2014', null, 'Una dotazione equilibrata per viaggi e accampamenti. Contiene provviste, illuminazione e strumenti essenziali per muoversi alcuni giorni lontano da città e locande.', '{"name":"Dotazione da esploratore","original_name":"Explorer''s Pack","category":"container","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":1000,"image_url":null,"notes":"Una dotazione equilibrata per viaggi e accampamenti. Contiene provviste, illuminazione e strumenti essenziali per muoversi alcuni giorni lontano da città e locande.","is_magic":false,"attunement_active":false,"source_id":"explorers-pack","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/explorers-pack","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":10,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"equipment-packs","bundle_contents":[{"source_id":"backpack","name":"Backpack","url":"/api/2014/equipment/backpack","quantity":1},{"source_id":"bedroll","name":"Bedroll","url":"/api/2014/equipment/bedroll","quantity":1},{"source_id":"mess-kit","name":"Mess Kit","url":"/api/2014/equipment/mess-kit","quantity":1},{"source_id":"tinderbox","name":"Tinderbox","url":"/api/2014/equipment/tinderbox","quantity":1},{"source_id":"torch","name":"Torch","url":"/api/2014/equipment/torch","quantity":10},{"source_id":"rations-1-day","name":"Rations (1 day)","url":"/api/2014/equipment/rations-1-day","quantity":10},{"source_id":"waterskin","name":"Waterskin","url":"/api/2014/equipment/waterskin","quantity":1},{"source_id":"rope-hempen-50-feet","name":"Rope, hempen (50 feet)","url":"/api/2014/equipment/rope-hempen-50-feet","quantity":1}]}'::jsonb),
  ('Attrezzatura da pesca', 'gear', '2014', null, 'Questo kit include un''asta di legno, filo di seta, galleggianti in sughero, ami in acciaio, piombini, esche in velluto e una rete a maglie strette.', '{"name":"Attrezzatura da pesca","original_name":"Fishing tackle","category":"gear","rules_version":"2014","qty":1,"weight":1.81,"volume":0,"value_cp":100,"image_url":null,"notes":"Questo kit include un''asta di legno, filo di seta, galleggianti in sughero, ami in acciaio, piombini, esche in velluto e una rete a maglie strette.","is_magic":false,"attunement_active":false,"source_id":"fishing-tackle","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/fishing-tackle","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Fiaschetta o boccale', 'container', '2014', null, 'Un recipiente personale per bere o conservare una piccola quantità di liquido. Può raccogliere campioni, condividere una bevanda o celare temporaneamente un oggetto minuto.', '{"name":"Fiaschetta o boccale","original_name":"Flask or tankard","category":"container","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":2,"image_url":null,"notes":"Un recipiente personale per bere o conservare una piccola quantità di liquido. Può raccogliere campioni, condividere una bevanda o celare temporaneamente un oggetto minuto.","is_magic":false,"attunement_active":false,"source_id":"flask-or-tankard","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/flask-or-tankard","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Kit di contraffazione', 'gear', '2014', null, 'Questa piccola scatola contiene una varietà di carte e pergamene, penne e inchiostri, sigilli e ceralacca, foglia d’oro e d’argento e altri materiali necessari per creare convincenti falsificazioni di documenti fisici. La competenza nell’uso di questo kit ti consente di aggiungere il tuo bonus di competenza a qualsiasi prova di abilità che effettui per creare una falsificazione fisica di un documento.', '{"name":"Kit di contraffazione","original_name":"Forgery Kit","category":"gear","rules_version":"2014","qty":1,"weight":2.27,"volume":0,"value_cp":1500,"image_url":null,"notes":"Questa piccola scatola contiene una varietà di carte e pergamene, penne e inchiostri, sigilli e ceralacca, foglia d’oro e d’argento e altri materiali necessari per creare convincenti falsificazioni di documenti fisici. La competenza nell’uso di questo kit ti consente di aggiungere il tuo bonus di competenza a qualsiasi prova di abilità che effettui per creare una falsificazione fisica di un documento.","is_magic":false,"attunement_active":false,"source_id":"forgery-kit","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/forgery-kit","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":15,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"kits","bundle_contents":[]}'::jsonb),
  ('Rampino', 'gear', '2014', null, 'Un gancio da usare con una corda per raggiungere sporgenze, fissare carichi o recuperare oggetti. Prima di affidargli il peso di una creatura è prudente verificare che abbia fatto presa.', '{"name":"Rampino","original_name":"Grappling hook","category":"gear","rules_version":"2014","qty":1,"weight":1.81,"volume":0,"value_cp":200,"image_url":null,"notes":"Un gancio da usare con una corda per raggiungere sporgenze, fissare carichi o recuperare oggetti. Prima di affidargli il peso di una creatura è prudente verificare che abbia fatto presa.","is_magic":false,"attunement_active":false,"source_id":"grappling-hook","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/grappling-hook","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Martello', 'gear', '2014', null, 'Un martello da lavoro per chiodi, cunei e piccole riparazioni. Può piantare chiodi da roccia, rompere materiali fragili o produrre deliberatamente un forte rumore.', '{"name":"Martello","original_name":"Hammer","category":"gear","rules_version":"2014","qty":1,"weight":1.36,"volume":0,"value_cp":100,"image_url":null,"notes":"Un martello da lavoro per chiodi, cunei e piccole riparazioni. Può piantare chiodi da roccia, rompere materiali fragili o produrre deliberatamente un forte rumore.","is_magic":false,"attunement_active":false,"source_id":"hammer","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/hammer","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Martello, mazza', 'gear', '2014', null, 'Una mazza pesante da lavoro, efficace contro porte, murature e ostacoli robusti. Richiede spazio per essere manovrata e difficilmente passa inosservata.', '{"name":"Martello, mazza","original_name":"Hammer, sledge","category":"gear","rules_version":"2014","qty":1,"weight":4.54,"volume":0,"value_cp":200,"image_url":null,"notes":"Una mazza pesante da lavoro, efficace contro porte, murature e ostacoli robusti. Richiede spazio per essere manovrata e difficilmente passa inosservata.","is_magic":false,"attunement_active":false,"source_id":"hammer-sledge","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/hammer-sledge","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Borsa del guaritore', 'gear', '2014', null, 'Questo kit è una borsa di pelle contenente bende, unguenti e stecche. Il kit ha dieci utilizzi. Come azione, puoi consumare un utilizzo del kit per stabilizzare una creatura che ha 0 punti ferita, senza bisogno di effettuare un tiro di Saggezza (Medicina).', '{"name":"Borsa del guaritore","original_name":"Healer''s Kit","category":"gear","rules_version":"2014","qty":1,"weight":1.36,"volume":0,"value_cp":500,"image_url":null,"notes":"Questo kit è una borsa di pelle contenente bende, unguenti e stecche. Il kit ha dieci utilizzi. Come azione, puoi consumare un utilizzo del kit per stabilizzare una creatura che ha 0 punti ferita, senza bisogno di effettuare un tiro di Saggezza (Medicina).","is_magic":false,"attunement_active":false,"source_id":"healers-kit","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/healers-kit","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"kits","bundle_contents":[]}'::jsonb),
  ('Kit di erboristeria', 'gear', '2014', null, 'Questo kit contiene una varietà di strumenti quali forbici, mortaio e pestello, sacchetti e fiale utilizzati dagli erboristi per creare rimedi e pozioni. La competenza con questo kit ti consente di aggiungere il tuo bonus di competenza a qualsiasi prova di abilità che effettui per identificare o applicare le erbe. Inoltre, la competenza con questo kit è necessaria per creare antitossine e pozioni curative.', '{"name":"Kit di erboristeria","original_name":"Herbalism Kit","category":"gear","rules_version":"2014","qty":1,"weight":1.36,"volume":0,"value_cp":500,"image_url":null,"notes":"Questo kit contiene una varietà di strumenti quali forbici, mortaio e pestello, sacchetti e fiale utilizzati dagli erboristi per creare rimedi e pozioni. La competenza con questo kit ti consente di aggiungere il tuo bonus di competenza a qualsiasi prova di abilità che effettui per identificare o applicare le erbe. Inoltre, la competenza con questo kit è necessaria per creare antitossine e pozioni curative.","is_magic":false,"attunement_active":false,"source_id":"herbalism-kit","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/herbalism-kit","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"kits","bundle_contents":[]}'::jsonb),
  ('Acqua santa (fiaschetta)', 'gear', '2014', null, 'Come azione, puoi spruzzare il contenuto di questa fiaschetta su una creatura entro 5 piedi da te oppure lanciarla fino a 20 piedi, frantumandola all’impatto. In entrambi i casi, effettua un attacco a distanza contro una creatura bersaglio, trattando l’acqua santa come un’arma improvvisata.

Se il bersaglio è un demone o un non-morto, subisce 2d6 danni da radiante.

Un chierico o un paladino può creare acqua santa eseguendo un rituale speciale.

Il rituale richiede 1 ora per essere eseguito, utilizza 25 mo di argento in polvere e richiede al lanciatore di spendere uno slot incantesimo di 1° livello.', '{"name":"Acqua santa (fiaschetta)","original_name":"Holy water (flask)","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":2500,"image_url":null,"notes":"Come azione, puoi spruzzare il contenuto di questa fiaschetta su una creatura entro 5 piedi da te oppure lanciarla fino a 20 piedi, frantumandola all’impatto. In entrambi i casi, effettua un attacco a distanza contro una creatura bersaglio, trattando l’acqua santa come un’arma improvvisata.\n\nSe il bersaglio è un demone o un non-morto, subisce 2d6 danni da radiante.\n\nUn chierico o un paladino può creare acqua santa eseguendo un rituale speciale.\n\nIl rituale richiede 1 ora per essere eseguito, utilizza 25 mo di argento in polvere e richiede al lanciatore di spendere uno slot incantesimo di 1° livello.","is_magic":false,"attunement_active":false,"source_id":"holy-water-flask","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/holy-water-flask","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":25,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Clessidra', 'gear', '2014', null, 'Una clessidra per misurare intervalli regolari. È utile per turni di guardia, esperimenti, rituali o enigmi nei quali il tempo deve essere seguito senza strumenti magici.', '{"name":"Clessidra","original_name":"Hourglass","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":2500,"image_url":null,"notes":"Una clessidra per misurare intervalli regolari. È utile per turni di guardia, esperimenti, rituali o enigmi nei quali il tempo deve essere seguito senza strumenti magici.","is_magic":false,"attunement_active":false,"source_id":"hourglass","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/hourglass","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":25,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Trappola da caccia', 'gear', '2014', null, 'Quando la attivi con la tua azione, questa trappola forma un anello d’acciaio seghettato che si chiude di scatto quando una creatura calpesta una piastra a pressione al centro. La trappola è fissata tramite una pesante catena a un oggetto immobile, come un albero o un picchetto conficcato nel terreno.

Una creatura che calpesta la piastra deve superare un tiro salvezza di Destrezza con CD 13 oppure subire 1d4 danni da perforazione e smettere di muoversi. Da quel momento in poi, finché la creatura non si libera dalla trappola, il suo movimento è limitato dalla lunghezza della catena (in genere lunga 3 piedi).

Una creatura può usare la propria azione per effettuare un tiro di Forza con CD 13; in caso di successo, libera se stessa o un’altra creatura alla sua portata. Ogni tiro fallito infligge 1 danno da perforazione alla creatura intrappolata.', '{"name":"Trappola da caccia","original_name":"Hunting trap","category":"gear","rules_version":"2014","qty":1,"weight":11.34,"volume":0,"value_cp":500,"image_url":null,"notes":"Quando la attivi con la tua azione, questa trappola forma un anello d’acciaio seghettato che si chiude di scatto quando una creatura calpesta una piastra a pressione al centro. La trappola è fissata tramite una pesante catena a un oggetto immobile, come un albero o un picchetto conficcato nel terreno.\n\nUna creatura che calpesta la piastra deve superare un tiro salvezza di Destrezza con CD 13 oppure subire 1d4 danni da perforazione e smettere di muoversi. Da quel momento in poi, finché la creatura non si libera dalla trappola, il suo movimento è limitato dalla lunghezza della catena (in genere lunga 3 piedi).\n\nUna creatura può usare la propria azione per effettuare un tiro di Forza con CD 13; in caso di successo, libera se stessa o un’altra creatura alla sua portata. Ogni tiro fallito infligge 1 danno da perforazione alla creatura intrappolata.","is_magic":false,"attunement_active":false,"source_id":"hunting-trap","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/hunting-trap","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Inchiostro (flacone da 1 oncia)', 'gear', '2014', null, 'Inchiostro per lettere, mappe e registri. Può anche marcare un bersaglio o lasciare tracce, ma il flacone va protetto per evitare che una perdita rovini il resto dell’equipaggiamento.', '{"name":"Inchiostro (flacone da 1 oncia)","original_name":"Ink (1 ounce bottle)","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":1000,"image_url":null,"notes":"Inchiostro per lettere, mappe e registri. Può anche marcare un bersaglio o lasciare tracce, ma il flacone va protetto per evitare che una perdita rovini il resto dell’equipaggiamento.","is_magic":false,"attunement_active":false,"source_id":"ink-1-ounce-bottle","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/ink-1-ounce-bottle","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":10,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Penna a inchiostro', 'gear', '2014', null, 'Una penna adatta a scrivere con l’inchiostro. Serve per copiare testi, aggiornare mappe, firmare documenti o preparare messaggi e falsificazioni credibili.', '{"name":"Penna a inchiostro","original_name":"Ink pen","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":2,"image_url":null,"notes":"Una penna adatta a scrivere con l’inchiostro. Serve per copiare testi, aggiornare mappe, firmare documenti o preparare messaggi e falsificazioni credibili.","is_magic":false,"attunement_active":false,"source_id":"ink-pen","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/ink-pen","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Brocca o caraffa', 'container', '2014', null, 'Una brocca per versare e trasportare liquidi. La bocca larga facilita il riempimento e permette di usarla anche per miscelare ingredienti o raccogliere piccoli oggetti.', '{"name":"Brocca o caraffa","original_name":"Jug or pitcher","category":"container","rules_version":"2014","qty":1,"weight":1.81,"volume":0,"value_cp":2,"image_url":null,"notes":"Una brocca per versare e trasportare liquidi. La bocca larga facilita il riempimento e permette di usarla anche per miscelare ingredienti o raccogliere piccoli oggetti.","is_magic":false,"attunement_active":false,"source_id":"jug-or-pitcher","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/jug-or-pitcher","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Scala (3 m)', 'gear', '2014', null, 'Una scala lunga circa 3 metri per superare dislivelli senza arrampicarsi. È ingombrante, ma può diventare una passerella, una leva o un sostegno improvvisato.', '{"name":"Scala (3 m)","original_name":"Ladder (10-foot)","category":"gear","rules_version":"2014","qty":1,"weight":11.34,"volume":0,"value_cp":10,"image_url":null,"notes":"Una scala lunga circa 3 metri per superare dislivelli senza arrampicarsi. È ingombrante, ma può diventare una passerella, una leva o un sostegno improvvisato.","is_magic":false,"attunement_active":false,"source_id":"ladder-10-foot","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/ladder-10-foot","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Lampada', 'gear', '2014', null, 'Una lampada proietta luce intensa in un raggio di 15 piedi e luce fioca per altri 30 piedi. Una volta accesa, brucia per 6 ore con una fiaschetta (1 pinta) di olio.', '{"name":"Lampada","original_name":"Lamp","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":50,"image_url":null,"notes":"Una lampada proietta luce intensa in un raggio di 15 piedi e luce fioca per altri 30 piedi. Una volta accesa, brucia per 6 ore con una fiaschetta (1 pinta) di olio.","is_magic":false,"attunement_active":false,"source_id":"lamp","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/lamp","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Lanterna a lente', 'gear', '2014', null, 'Una lanterna «bullseye» proietta una luce intensa in un cono di 60 piedi e una luce fioca per altri 60 piedi. Una volta accesa, brucia per 6 ore con una fiaschetta (1 pinta) di olio.', '{"name":"Lanterna a lente","original_name":"Lantern, bullseye","category":"gear","rules_version":"2014","qty":1,"weight":0.91,"volume":0,"value_cp":1000,"image_url":null,"notes":"Una lanterna «bullseye» proietta una luce intensa in un cono di 60 piedi e una luce fioca per altri 60 piedi. Una volta accesa, brucia per 6 ore con una fiaschetta (1 pinta) di olio.","is_magic":false,"attunement_active":false,"source_id":"lantern-bullseye","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/lantern-bullseye","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":10,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Lanterna schermabile', 'gear', '2014', null, 'Una lanterna a cappuccio proietta una luce intensa in un raggio di 30 piedi e una luce fioca per altri 30 piedi. Una volta accesa, brucia per 6 ore con una fiaschetta (1 pinta) di olio. Come azione, puoi abbassare il cappuccio, riducendo la luce a luce fioca in un raggio di 5 piedi.', '{"name":"Lanterna schermabile","original_name":"Lantern, hooded","category":"gear","rules_version":"2014","qty":1,"weight":0.91,"volume":0,"value_cp":500,"image_url":null,"notes":"Una lanterna a cappuccio proietta una luce intensa in un raggio di 30 piedi e una luce fioca per altri 30 piedi. Una volta accesa, brucia per 6 ore con una fiaschetta (1 pinta) di olio. Come azione, puoi abbassare il cappuccio, riducendo la luce a luce fioca in un raggio di 5 piedi.","is_magic":false,"attunement_active":false,"source_id":"lantern-hooded","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/lantern-hooded","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Sacchettino di sabbia', 'gear', '2014', null, 'Un piccolo sacchetto di sabbia, che solitamente si trova nello zaino di uno studioso.', '{"name":"Sacchettino di sabbia","original_name":"Little bag of sand","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":0,"image_url":null,"notes":"Un piccolo sacchetto di sabbia, che solitamente si trova nello zaino di uno studioso.","is_magic":false,"attunement_active":false,"source_id":"little-bag-of-sand","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/little-bag-of-sand","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":0,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Lucchetto', 'gear', '2014', null, 'Insieme alla serratura viene fornita una chiave. Senza la chiave, una creatura esperta nell’uso degli attrezzi da ladro può scassinare questa serratura con un tiro di Destrezza riuscito con CD 15. Il tuo GM può decidere che siano disponibili serrature migliori a prezzi più elevati.', '{"name":"Lucchetto","original_name":"Lock","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":1000,"image_url":null,"notes":"Insieme alla serratura viene fornita una chiave. Senza la chiave, una creatura esperta nell’uso degli attrezzi da ladro può scassinare questa serratura con un tiro di Destrezza riuscito con CD 15. Il tuo GM può decidere che siano disponibili serrature migliori a prezzi più elevati.","is_magic":false,"attunement_active":false,"source_id":"lock","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/lock","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":10,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Lente d’ingrandimento', 'gear', '2014', null, 'Questa lente permette di osservare da vicino oggetti di piccole dimensioni. È utile anche come sostituto di selce e acciarino per accendere il fuoco. Per accendere un fuoco con una lente d’ingrandimento sono necessari una luce intensa quanto quella solare per focalizzare i raggi, dell’esca per innescare la fiamma e circa 5 minuti affinché il fuoco prenda piede.

Una lente d’ingrandimento conferisce vantaggio a qualsiasi prova di abilità effettuata per valutare o ispezionare un oggetto piccolo o molto dettagliato.', '{"name":"Lente d’ingrandimento","original_name":"Magnifying glass","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":10000,"image_url":null,"notes":"Questa lente permette di osservare da vicino oggetti di piccole dimensioni. È utile anche come sostituto di selce e acciarino per accendere il fuoco. Per accendere un fuoco con una lente d’ingrandimento sono necessari una luce intensa quanto quella solare per focalizzare i raggi, dell’esca per innescare la fiamma e circa 5 minuti affinché il fuoco prenda piede.\n\nUna lente d’ingrandimento conferisce vantaggio a qualsiasi prova di abilità effettuata per valutare o ispezionare un oggetto piccolo o molto dettagliato.","is_magic":false,"attunement_active":false,"source_id":"magnifying-glass","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/magnifying-glass","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":100,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Manette', 'gear', '2014', null, 'Queste manette metalliche possono immobilizzare una creatura di taglia Piccola o Media. Per liberarsi dalle manette è necessario superare un tiro di Destrezza con CD 20. Per romperle è necessario superare un tiro di Forza con CD 20.

Ogni paio di manette è dotato di una chiave. Senza la chiave, una creatura esperta nell’uso degli attrezzi da ladro può scassinare la serratura delle manette con un tiro di Destrezza riuscito con CD 15. Le manette hanno 15 punti ferita.', '{"name":"Manette","original_name":"Manacles","category":"gear","rules_version":"2014","qty":1,"weight":2.72,"volume":0,"value_cp":200,"image_url":null,"notes":"Queste manette metalliche possono immobilizzare una creatura di taglia Piccola o Media. Per liberarsi dalle manette è necessario superare un tiro di Destrezza con CD 20. Per romperle è necessario superare un tiro di Forza con CD 20.\n\nOgni paio di manette è dotato di una chiave. Senza la chiave, una creatura esperta nell’uso degli attrezzi da ladro può scassinare la serratura delle manette con un tiro di Destrezza riuscito con CD 15. Le manette hanno 15 punti ferita.","is_magic":false,"attunement_active":false,"source_id":"manacles","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/manacles","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Gavetta', 'gear', '2014', null, 'Questa scatola di latta contiene una tazza e delle posate semplici. La scatola si chiude a scatto e un lato può essere utilizzato come padella, mentre l’altro come piatto o ciotola poco profonda.', '{"name":"Gavetta","original_name":"Mess Kit","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":20,"image_url":null,"notes":"Questa scatola di latta contiene una tazza e delle posate semplici. La scatola si chiude a scatto e un lato può essere utilizzato come padella, mentre l’altro come piatto o ciotola poco profonda.","is_magic":false,"attunement_active":false,"source_id":"mess-kit","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/mess-kit","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"kits","bundle_contents":[]}'::jsonb),
  ('Specchio d’acciaio', 'gear', '2014', null, 'Uno specchio resistente, utile per osservare dietro angoli, sotto porte o dentro aperture senza esporsi direttamente. Può riflettere luce e segnali, anche se l’immagine è meno nitida del vetro.', '{"name":"Specchio d’acciaio","original_name":"Mirror, steel","category":"gear","rules_version":"2014","qty":1,"weight":0.23,"volume":0,"value_cp":500,"image_url":null,"notes":"Uno specchio resistente, utile per osservare dietro angoli, sotto porte o dentro aperture senza esporsi direttamente. Può riflettere luce e segnali, anche se l’immagine è meno nitida del vetro.","is_magic":false,"attunement_active":false,"source_id":"mirror-steel","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/mirror-steel","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Olio (ampolla)', 'gear', '2014', null, 'L’olio è solitamente contenuto in una fiaschetta di argilla che ne contiene 1 pinta.

Come azione, puoi spruzzare l’olio contenuto in questa fiaschetta su una creatura entro 5 piedi da te oppure lanciarla fino a 20 piedi di distanza, frantumandola all’impatto. Effettua un attacco a distanza contro una creatura o un oggetto bersaglio, trattando l’olio come un’arma improvvisata.

In caso di colpo andato a segno, il bersaglio viene ricoperto d’olio. Se il bersaglio subisce danni da fuoco prima che l’olio si asciughi (dopo 1 minuto), subisce ulteriori 5 danni da fuoco causati dall’olio infuocato.

Puoi anche versare una fiaschetta di olio sul terreno per coprire un’area di 5 piedi per 5 piedi, a condizione che la superficie sia piana.

Se acceso, l’olio brucia per 2 round e infligge 5 danni da fuoco a qualsiasi creatura che entri nell’area o che concluda il proprio turno all’interno di essa. Una creatura può subire questo danno solo una volta per turno.', '{"name":"Olio (ampolla)","original_name":"Oil (flask)","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":10,"image_url":null,"notes":"L’olio è solitamente contenuto in una fiaschetta di argilla che ne contiene 1 pinta.\n\nCome azione, puoi spruzzare l’olio contenuto in questa fiaschetta su una creatura entro 5 piedi da te oppure lanciarla fino a 20 piedi di distanza, frantumandola all’impatto. Effettua un attacco a distanza contro una creatura o un oggetto bersaglio, trattando l’olio come un’arma improvvisata.\n\nIn caso di colpo andato a segno, il bersaglio viene ricoperto d’olio. Se il bersaglio subisce danni da fuoco prima che l’olio si asciughi (dopo 1 minuto), subisce ulteriori 5 danni da fuoco causati dall’olio infuocato.\n\nPuoi anche versare una fiaschetta di olio sul terreno per coprire un’area di 5 piedi per 5 piedi, a condizione che la superficie sia piana.\n\nSe acceso, l’olio brucia per 2 round e infligge 5 danni da fuoco a qualsiasi creatura che entri nell’area o che concluda il proprio turno all’interno di essa. Una creatura può subire questo danno solo una volta per turno.","is_magic":false,"attunement_active":false,"source_id":"oil-flask","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/oil-flask","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Orb', 'gear', '2014', null, 'Un focus arcano è un oggetto speciale — una sfera, un cristallo, una verga, un bastone appositamente costruito, un pezzo di legno simile a una bacchetta o un oggetto simile — progettato per incanalare il potere degli incantesimi arcani. Uno stregone, un warlock o un mago può utilizzare tale oggetto come focus per lanciare incantesimi.', '{"name":"Orb","original_name":"Orb","category":"gear","rules_version":"2014","qty":1,"weight":1.36,"volume":0,"value_cp":2000,"image_url":null,"notes":"Un focus arcano è un oggetto speciale — una sfera, un cristallo, una verga, un bastone appositamente costruito, un pezzo di legno simile a una bacchetta o un oggetto simile — progettato per incanalare il potere degli incantesimi arcani. Uno stregone, un warlock o un mago può utilizzare tale oggetto come focus per lanciare incantesimi.","is_magic":false,"attunement_active":false,"source_id":"orb","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/orb","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":20,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"arcane-foci","bundle_contents":[]}'::jsonb),
  ('Carta (un foglio)', 'gear', '2014', null, 'Un singolo foglio adatto a lettere, schizzi e appunti. Può conservare indizi, diventare una mappa improvvisata o essere piegato per lasciare un messaggio discreto.', '{"name":"Carta (un foglio)","original_name":"Paper (one sheet)","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":20,"image_url":null,"notes":"Un singolo foglio adatto a lettere, schizzi e appunti. Può conservare indizi, diventare una mappa improvvisata o essere piegato per lasciare un messaggio discreto.","is_magic":false,"attunement_active":false,"source_id":"paper-one-sheet","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/paper-one-sheet","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Pergamena (un foglio)', 'gear', '2014', null, 'Un foglio di pergamena più resistente della carta comune. È indicato per mappe, contratti, formule e documenti destinati a essere trasportati o conservati a lungo.', '{"name":"Pergamena (un foglio)","original_name":"Parchment (one sheet)","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":10,"image_url":null,"notes":"Un foglio di pergamena più resistente della carta comune. È indicato per mappe, contratti, formule e documenti destinati a essere trasportati o conservati a lungo.","is_magic":false,"attunement_active":false,"source_id":"parchment-one-sheet","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/parchment-one-sheet","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Profumo (fiala)', 'gear', '2014', null, 'Una fragranza concentrata in una piccola fiala. Può completare un travestimento sociale, coprire altri odori o lasciare una traccia riconoscibile durante un’indagine.', '{"name":"Profumo (fiala)","original_name":"Perfume (vial)","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":500,"image_url":null,"notes":"Una fragranza concentrata in una piccola fiala. Può completare un travestimento sociale, coprire altri odori o lasciare una traccia riconoscibile durante un’indagine.","is_magic":false,"attunement_active":false,"source_id":"perfume-vial","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/perfume-vial","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Picozza da minatore', 'gear', '2014', null, 'Una picozza da lavoro per roccia e terreno compatto. Può aprire un passaggio lentamente, cercare cavità o indebolire una struttura, producendo però molto rumore.', '{"name":"Picozza da minatore","original_name":"Pick, miner''s","category":"gear","rules_version":"2014","qty":1,"weight":4.54,"volume":0,"value_cp":200,"image_url":null,"notes":"Una picozza da lavoro per roccia e terreno compatto. Può aprire un passaggio lentamente, cercare cavità o indebolire una struttura, producendo però molto rumore.","is_magic":false,"attunement_active":false,"source_id":"pick-miners","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/pick-miners","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Chiodo da roccia', 'gear', '2014', null, 'Un chiodo metallico da fissare nella roccia o nel legno. Con una corda crea ancoraggi, assicura una discesa, blocca una porta o sostiene un semplice allarme.', '{"name":"Chiodo da roccia","original_name":"Piton","category":"gear","rules_version":"2014","qty":1,"weight":0.11,"volume":0,"value_cp":5,"image_url":null,"notes":"Un chiodo metallico da fissare nella roccia o nel legno. Con una corda crea ancoraggi, assicura una discesa, blocca una porta o sostiene un semplice allarme.","is_magic":false,"attunement_active":false,"source_id":"piton","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/piton","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Veleno, base (fiala)', 'gear', '2014', null, 'È possibile utilizzare il veleno contenuto in questa fiala per ricoprire un''arma da taglio o da perforazione oppure fino a tre munizioni. L''applicazione del veleno richiede un''azione. Una creatura colpita dall’arma o dalle munizioni avvelenate deve effettuare un tiro salvezza di Costituzione con CD 10 o subire 1d4 danni da veleno. Una volta applicato, il veleno mantiene la sua efficacia per 1 minuto prima di seccarsi.', '{"name":"Veleno, base (fiala)","original_name":"Poison, basic (vial)","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":10000,"image_url":null,"notes":"È possibile utilizzare il veleno contenuto in questa fiala per ricoprire un''arma da taglio o da perforazione oppure fino a tre munizioni. L''applicazione del veleno richiede un''azione. Una creatura colpita dall’arma o dalle munizioni avvelenate deve effettuare un tiro salvezza di Costituzione con CD 10 o subire 1d4 danni da veleno. Una volta applicato, il veleno mantiene la sua efficacia per 1 minuto prima di seccarsi.","is_magic":false,"attunement_active":false,"source_id":"poison-basic-vial","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/poison-basic-vial","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":100,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Kit del velenatore', 'gear', '2014', null, 'Un kit da avvelenatore include fiale, sostanze chimiche e altre attrezzature necessarie per la creazione di veleni. La competenza con questo kit ti consente di aggiungere il tuo bonus di competenza a qualsiasi prova di abilità che effettui per creare o utilizzare veleni.', '{"name":"Kit del velenatore","original_name":"Poisoner''s Kit","category":"gear","rules_version":"2014","qty":1,"weight":0.91,"volume":0,"value_cp":5000,"image_url":null,"notes":"Un kit da avvelenatore include fiale, sostanze chimiche e altre attrezzature necessarie per la creazione di veleni. La competenza con questo kit ti consente di aggiungere il tuo bonus di competenza a qualsiasi prova di abilità che effettui per creare o utilizzare veleni.","is_magic":false,"attunement_active":false,"source_id":"poisoners-kit","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/poisoners-kit","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":50,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"kits","bundle_contents":[]}'::jsonb),
  ('Palo (10 piedi)', 'gear', '2014', null, 'Un lungo palo per sondare terreno, soffitti e meccanismi mantenendo distanza. È utile contro trappole e passaggi instabili, ma scomodo negli spazi stretti.', '{"name":"Palo (10 piedi)","original_name":"Pole (10-foot)","category":"gear","rules_version":"2014","qty":1,"weight":3.18,"volume":0,"value_cp":5,"image_url":null,"notes":"Un lungo palo per sondare terreno, soffitti e meccanismi mantenendo distanza. È utile contro trappole e passaggi instabili, ma scomodo negli spazi stretti.","is_magic":false,"attunement_active":false,"source_id":"pole-10-foot","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/pole-10-foot","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Pentola, ferro', 'container', '2014', null, 'Una pentola resistente per cucinare e bollire acqua. Può raccogliere liquidi, proteggere piccoli oggetti dal calore o produrre rumore come segnale improvvisato.', '{"name":"Pentola, ferro","original_name":"Pot, iron","category":"container","rules_version":"2014","qty":1,"weight":4.54,"volume":0,"value_cp":200,"image_url":null,"notes":"Una pentola resistente per cucinare e bollire acqua. Può raccogliere liquidi, proteggere piccoli oggetti dal calore o produrre rumore come segnale improvvisato.","is_magic":false,"attunement_active":false,"source_id":"pot-iron","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/pot-iron","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Borsa', 'container', '2014', null, 'Una sacca di stoffa o di cuoio può contenere fino a 20 proiettili da fionda o 50 aghi da cerbottana, tra le altre cose. Una sacca suddivisa in scomparti per contenere i componenti degli incantesimi è chiamata sacca per componenti (descritta in precedenza in questa sezione).', '{"name":"Borsa","original_name":"Pouch","category":"container","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":50,"image_url":null,"notes":"Una sacca di stoffa o di cuoio può contenere fino a 20 proiettili da fionda o 50 aghi da cerbottana, tra le altre cose. Una sacca suddivisa in scomparti per contenere i componenti degli incantesimi è chiamata sacca per componenti (descritta in precedenza in questa sezione).","is_magic":false,"attunement_active":false,"source_id":"pouch","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/pouch","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Dotazione da sacerdote', 'container', '2014', null, 'Una dotazione per sacerdoti itineranti. Combina provviste da viaggio con oggetti utili a cerimonie, offerte e cura di un piccolo luogo di culto.', '{"name":"Dotazione da sacerdote","original_name":"Priest''s Pack","category":"container","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":1900,"image_url":null,"notes":"Una dotazione per sacerdoti itineranti. Combina provviste da viaggio con oggetti utili a cerimonie, offerte e cura di un piccolo luogo di culto.","is_magic":false,"attunement_active":false,"source_id":"priests-pack","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/priests-pack","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":19,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"equipment-packs","bundle_contents":[{"source_id":"backpack","name":"Backpack","url":"/api/2014/equipment/backpack","quantity":1},{"source_id":"blanket","name":"Blanket","url":"/api/2014/equipment/blanket","quantity":1},{"source_id":"candle","name":"Candle","url":"/api/2014/equipment/candle","quantity":10},{"source_id":"tinderbox","name":"Tinderbox","url":"/api/2014/equipment/tinderbox","quantity":1},{"source_id":"rations-1-day","name":"Rations (1 day)","url":"/api/2014/equipment/rations-1-day","quantity":2},{"source_id":"waterskin","name":"Waterskin","url":"/api/2014/equipment/waterskin","quantity":1},{"source_id":"alms-box","name":"Alms box","url":"/api/2014/equipment/alms-box","quantity":1},{"source_id":"block-of-incense","name":"Block of incense","url":"/api/2014/equipment/block-of-incense","quantity":2},{"source_id":"censer","name":"Censer","url":"/api/2014/equipment/censer","quantity":1},{"source_id":"vestments","name":"Vestments","url":"/api/2014/equipment/vestments","quantit