  ('Sapone', 'gear', '2014', null, 'Una saponetta per pulire persone, tessuti e attrezzatura. Oltre all’igiene può rendere scivolosa una superficie, individuare piccole perdite o cancellare tracce e odori.', '{"name":"Sapone","original_name":"Soap","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":2,"image_url":null,"notes":"Una saponetta per pulire persone, tessuti e attrezzatura. Oltre all’igiene può rendere scivolosa una superficie, individuare piccole perdite o cancellare tracce e odori.","is_magic":false,"attunement_active":false,"source_id":"soap","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/soap","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
