  ('Spike, ferro', 'gear', '2014', null, 'Un robusto cuneo di ferro. Può bloccare una porta, fissare una corda, stabilizzare un oggetto o creare un ostacolo, purché sia martellato in un supporto adeguato.', '{"name":"Spike, ferro","original_name":"Spike, iron","category":"gear","rules_version":"2014","qty":1,"weight":2.27,"volume":0,"value_cp":10,"image_url":null,"notes":"Un robusto cuneo di ferro. Può bloccare una porta, fissare una corda, stabilizzare un oggetto o creare un ostacolo, purché sia martellato in un supporto adeguato.","is_magic":false,"attunement_active":false,"source_id":"spike-iron","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/spike-iron","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Ramoscello di vischio', 'gear', '2014', null, 'Un focus druidico potrebbe essere un rametto di vischio o di agrifoglio, una bacchetta o uno scettro realizzati in tasso o in un altro legno speciale, un bastone ricavato interamente da un albero vivo, oppure un oggetto totemico che incorpora piume, pelliccia, ossa e denti di animali sacri. Un druido può utilizzare un oggetto del genere come focus per lanciare incantesimi.', '{"name":"Ramoscello di vischio","original_name":"Sprig of mistletoe","category":"gear","rules_version":"2014","qty":1,"weight":0,"volume":0,"value_cp":100,"image_url":null,"notes":"Un focus druidico potrebbe essere un rametto di vischio o di agrifoglio, una bacchetta o uno scettro realizzati in tasso o in un altro legno speciale, un bastone ricavato interamente da un albero vivo, oppure un oggetto totemico che incorpora piume, pelliccia, ossa e denti di animali sacri. Un druido può utilizzare un oggetto del genere come focus per lanciare incantesimi.","is_magic":false,"attunement_active":false,"source_id":"sprig-of-mistletoe","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/sprig-of-mistletoe","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"druidic-foci","bundle_contents":[]}'::jsonb),
  ('Cannocchiale', 'gear', '2014', null, 'Gli oggetti osservati attraverso un cannocchiale appaiono ingranditi al doppio delle loro dimensioni.', '{"name":"Cannocchiale","original_name":"Spyglass","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":100000,"image_url":null,"notes":"Gli oggetti osservati attraverso un cannocchiale appaiono ingranditi al doppio delle loro dimensioni.","is_magic":false,"attunement_active":false,"source_id":"spyglass","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/spyglass","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1000,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Staff', 'gear', '2014', null, 'Un focus arcano è un oggetto speciale — una sfera, un cristallo, una verga, un bastone appositamente costruito, un pezzo di legno simile a una bacchetta o un oggetto simile — progettato per incanalare il potere degli incantesimi arcani. Uno stregone, un warlock o un mago può utilizzare tale oggetto come focus per lanciare incantesimi.', '{"name":"Staff","original_name":"Staff","category":"gear","rules_version":"2014","qty":1,"weight":1.81,"volume":0,"value_cp":500,"image_url":null,"notes":"Un focus arcano è un oggetto speciale — una sfera, un cristallo, una verga, un bastone appositamente costruito, un pezzo di legno simile a una bacchetta o un oggetto simile — progettato per incanalare il potere degli incantesimi arcani. Uno stregone, un warlock o un mago può utilizzare tale oggetto come focus per lanciare incantesimi.","is_magic":false,"attunement_active":false,"source_id":"staff","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/staff","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"arcane-foci","bundle_contents":[]}'::jsonb),
