  ('Tenda (due persone)', 'gear', '2014', null, 'Un riparo in tela semplice e trasportabile, una tenda che può ospitare due persone.', '{"name":"Tenda (due persone)","original_name":"Tent, two-person","category":"gear","rules_version":"2014","qty":1,"weight":9.07,"volume":0,"value_cp":200,"image_url":null,"notes":"Un riparo in tela semplice e trasportabile, una tenda che può ospitare due persone.","is_magic":false,"attunement_active":false,"source_id":"tent-two-person","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/tent-two-person","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":2,"moneta":"mo"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
  ('Acciarino e pietra focaia', 'gear', '2014', null, 'Questo piccolo contenitore contiene una pietra focaia, un acciarino e dell’esca (di solito un panno asciutto imbevuto di olio leggero) utilizzati per accendere un fuoco. Usarlo per accendere una torcia — o qualsiasi altra cosa con combustibile abbondante ed esposto — richiede un’azione.

Accendere qualsiasi altro fuoco richiede 1 minuto.', '{"name":"Acciarino e pietra focaia","original_name":"Tinderbox","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":50,"image_url":null,"notes":"Questo piccolo contenitore contiene una pietra focaia, un acciarino e dell’esca (di solito un panno asciutto imbevuto di olio leggero) utilizzati per accendere un fuoco. Usarlo per accendere una torcia — o qualsiasi altra cosa con combustibile abbondante ed esposto — richiede un’azione.\n\nAccendere qualsiasi altro fuoco richiede 1 minuto.","is_magic":false,"attunement_active":false,"source_id":"tinderbox","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/tinderbox","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":5,"moneta":"ma"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
