  ('Pietra per affilare', 'gear', '2014', null, 'Una pietra abrasiva per mantenere lame e utensili. Durante una pausa può servire alla manutenzione dell’equipaggiamento o a produrre polvere e scintille con il materiale adatto.', '{"name":"Pietra per affilare","original_name":"Whetstone","category":"gear","rules_version":"2014","qty":1,"weight":0.45,"volume":0,"value_cp":1,"image_url":null,"notes":"Una pietra abrasiva per mantenere lame e utensili. Durante una pausa può servire alla manutenzione dell’equipaggiamento o a produrre polvere e scintille con il materiale adatto.","is_magic":false,"attunement_active":false,"source_id":"whetstone","source_label":"SRD 5.1","source_edition":"D&D 5e (regole 2014)","source_url":"https://www.dnd5eapi.co/api/2014/equipment/whetstone","source_kind":"equipment","original_category":"equipaggiamento","cost":{"quantita":1,"moneta":"mr"},"equipable":false,"compatible_equip_slots":[],"equip_slot":null,"equip_slots":[],"sovrapponibile":false,"max_volume":null,"ammunition_type":null,"gear_category":"standard-gear","bundle_contents":[]}'::jsonb),
